Hi,

Using gl.grm yesterday I found that when plotting the heatmap, the legend would always show up in the middle of the chart - not useful. I just slightly changed the code of the gl.grm function to allow specification of x,y coords for the legend, which I figure may be a useful feature anyway to include in the next update of the package.

gl.grm.fixed <- function(x, legendx, legendy, plotheatmap=TRUE, verbose=NULL, ...){

  # CHECK IF PACKAGES ARE INSTALLED
  pkg <- "rrBLUP"
  if (!(requireNamespace(pkg, quietly = TRUE))) {
    stop("Package ",pkg," needed for this function to work. Please install it.") }
  pkg <- "gplots"
  if (!(requireNamespace(pkg, quietly = TRUE))) {
    stop("Package ",pkg," needed for this function to work. Please install it.") }

  # TRAP COMMAND, SET VERSION

  funname <- match.call()[[1]]
  build <- "Jacob"

  # SET VERBOSITY

  if (is.null(verbose)){
    if(!is.null(x@other$verbose)){
      verbose <- x@other$verbose
    } else {
      verbose <- 2
    }
  }

  if (verbose < 0 | verbose > 5){
    cat(paste("  Warning: Parameter 'verbose' must be an integer between 0 [silent] and 5 [full report], set to 2\n"))
    verbose <- 2
  }

  # FLAG SCRIPT START

  if (verbose >= 1){
    if(verbose==5){
      cat("Starting",funname,"[ Build =",build,"]\n")
    } else {
      cat("Starting",funname,"\n")
    }
  }

  # STANDARD ERROR CHECKING

  if(class(x)!="genlight") {
    stop("Fatal Error: genlight object required!\n")
  }

  if (all(x@ploidy == 1)){
    stop("  Detected Tag Presence/Absence (SilicoDArT) data. Please provide a SNP dataset\n")
  } else if (all(x@ploidy == 2)){
    cat("  Processing a SNP dataset\n")
  } else {
    stop("Fatal Error: Ploidy must be universally 1 (fragment P/A data) or 2 (SNP data)!\n")
  }

  # Set a population if none is specified (such as if the genlight object has been generated manually)
  if (is.null(pop(x)) | is.na <http://is.na>(length(pop(x))) | length(pop(x)) <= 0) {
    if (verbose >= 2){ cat("  Population assignments not detected, individuals assigned to a single population labelled 'pop1'\n")}
    pop(x) <- array("pop1",dim = nInd(x))
    pop(x) <- as.factor(pop(x))
  }

  # DO THE JOB

  # function to replicate defaults colors of ggplot
  gg_color_hue <- function(n) {
    hues = seq(15, 375, length = n + 1)
    return (hcl(h = hues, l = 65, c = 100)[1:n])
  }

  # assigning colors to populations
  colors_pop_temp <- gg_color_hue(length(levels(pop(x))))
  names(colors_pop_temp) <- as.character(levels(x$pop))
  cols_pops <- as.data.frame(cbind(names(colors_pop_temp),colors_pop_temp))
  colnames(cols_pops) <- c("pop","colour")
  df_pops <- as.data.frame(x$pop)
  colnames(df_pops) <- c("pop")
  cols_pops <- merge(df_pops,cols_pops,by="pop")

  # calculating the realized additive relationship matrix

  G <- rrBLUP::A.mat(as.matrix(x)-1, ...)

  # creating color palette for probability of identity by descent
  cool = rainbow(50, start=rgb2hsv(col2rgb('cyan'))[1], end=rgb2hsv(col2rgb('blue'))[1])
  warm = rainbow(50, start=rgb2hsv(col2rgb('red'))[1], end=rgb2hsv(col2rgb('yellow'))[1])
  cols = c(rev(cool), rev(warm))
  mypalette <- colorRampPalette(cols)(255)

  if(plotheatmap==T){
    # plotting heatmap
    gplots::heatmap.2(G,col=mypalette,dendrogram="column",ColSideColors=as.character(cols_pops$colour),RowSideColors=as.character(cols_pops$colour), trace = "none", density.info <http://density.info> = "none",scale="none",main="Probability of identity by descent")
    legend(legendx,legendy,legend=unique(cols_pops$pop),fill=unique(cols_pops$colour),cex=0.75,title="Populations")
  }

  # FLAG SCRIPT END

  if(verbose >= 1){
    cat("Completed:",funname,"\n")
  }

  return (G)
}

Hope this is useful.

Rhiannon
